// nodeType -> symbol id, for renderer lookups
export const NODE_TYPE_TO_SYMBOL_ID = {
  STANDARD_COMBAT: "icon-standard-combat",
  OVERSEER: "icon-overseer",
  TIMED_CHALLENGE: "icon-timed-challenge",
  ORDEAL: "icon-ordeal",
  REFLECTION_CHAMBER: "icon-reflection-chamber",
  REST_POINT: "icon-rest-point",
  HELL_LORD: "icon-hell-lord",
};

// Builds the <defs><symbol>...</symbol></defs> block once per document.
export function buildIconDefsMarkup() {
  const symbols = Object.entries(ICON_SYMBOL_MARKUP)
    .map(
      ([id, inner]) =>
        '<symbol id="' + id + '" viewBox="' + ICON_VIEWBOX + '">' + inner + '</symbol>'
    )
    .join("");
  return '<defs>' + symbols + '</defs>';
}
